#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const dsRoot = path.resolve(__dirname, '..');
const cssRoot = path.join(dsRoot, 'assets/css');
const version = fs.readFileSync(path.join(dsRoot, 'VERSION'), 'utf8').trim();

const vendorImports = [
  '../vendor/fontawesome/css/fontawesome.min.css?v=7.2.0',
  '../vendor/fontawesome/css/solid.min.css?v=7.2.0',
  '../vendor/fontawesome/css/brands.min.css?v=7.2.0',
];

const modules = [
  'tokens.css',
  'foundation.css',
  'components.css',
  'documents.css',
  'advanced.css',
];

function readModule(file) {
  const source = fs.readFileSync(path.join(cssRoot, file), 'utf8').trim();
  return [
    '',
    `/* ===== ${file} ===== */`,
    source,
    '',
  ].join('\n');
}

const bundle = [
  `/* Business PRO Design System ${version}`,
  '   Generated by tools/generate-css-bundle.js.',
  '   Edit source modules, not this file. */',
  ...vendorImports.map((href) => `@import url("${href}");`),
  ...modules.map(readModule),
].join('\n');

fs.writeFileSync(path.join(cssRoot, 'business-pro.bundle.css'), `${bundle.trim()}\n`);
console.log(`Generated assets/css/business-pro.bundle.css for DS ${version}.`);

// Minificare conservatoare (fără dependențe): scoate comentariile și spațiile
// redundante, dar nu atinge string-uri/URL-uri (nu conțin ghilimele cu ;{}).
function minifyCss(source) {
  return source
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/\s+/g, ' ')
    .replace(/\s*([{}:;,>])\s*/g, '$1')
    .replace(/;}/g, '}')
    .trim();
}

const minified = `/* Business PRO DS ${version} — generat de tools/generate-css-bundle.js */\n${minifyCss(bundle)}\n`;
fs.writeFileSync(path.join(cssRoot, 'business-pro.bundle.min.css'), minified);
console.log(`Generated assets/css/business-pro.bundle.min.css for DS ${version}.`);
